pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based: the first retry (attempt = 1) has had zero
    // doublings, so shift by `attempt - 1`. Saturating multiplication keeps
    // large attempts at the cap instead of wrapping to zero.
    let shift = attempt.saturating_sub(1).min(63);
    let raw = config.base_delay_ms.saturating_mul(1u64 << shift);
    if raw > config.max_delay_ms {
        config.max_delay_ms
    } else {
        raw
    }
}

